# R@ thresholds
def recall_at(fpi_target):
    idx = np.argmin(np.abs(np.array(fpi_levels) - fpi_target))
    return tpr_values[idx]

print("----------------------------")
print("R@0.05 =", f"{recall_at(0.05):.3f}")
print("R@0.3 =", f"{recall_at(0.3):.3f}")
print("R@0.5  =", f"{recall_at(0.5):.3f}")      # nearest point
print("R@1.0  =", recall_at(1.0))      # nearest point
print("AUC    =", np.trapz(tpr_values, fpi_levels))

